const tmpDate = new Date(
  today.getFullYear(),
  $h.месяц - 1,          // JS-месяцы 0–11, поэтому месяц - 1
  today.getDate()
);

const ustData = tmpDate.addMonths(-1);

// границы месяца уст_дата
const periodStart = ustData.beginMonth();
const periodEnd   = ustData.endMonth();

// 1) Тянем данные из регистра только по проекту, без отбора по датам
let tableWork = await from("records.ведомость_раб_врем")
  .where("проект_заказ = @proj")
  .parameter("proj", $h.проект_заказ)
  .select([
    "period",      // поле с датой периода (приходит как строка)
    "сотрудники"
  ])
  .getDisplays()
  .query();

// 2) Уже в DataTable фильтруем по датам, а не по строкам
