  .filter(row => {
    const periodStr = row["period"];
    if (!periodStr) return false;

    // Строку → Date (по аналогии с примерами в dateFunctions)
    const periodDate = new Date(periodStr);

    return periodDate >= periodStart && periodDate <= periodEnd;
  });

